here<-dirname(normalizePath(sub('^--file=','',grep('^--file=',commandArgs(FALSE),value=TRUE)),winslash='/'));source(file.path(here,'common.R'))
a<-args_named();root<-normal(need(a,'analysis'));maps<-normal(need(a,'maps'));figs<-normal(need(a,'summary-figures'));clim<-normal(need(a,'climate-figure'));review<-normal(need(a,'review-tables'));out<-normal(need(a,'out'),FALSE);stopifnot(!dir.exists(out))
v<-fromJSON(file.path(root,'independent_verification/status.json'));stopifnot(v$status=='INDEPENDENT_VERIFICATION_PASS',v$profiles==2036,fromJSON(file.path(review,'status.json'))$status=='REVIEW_TABLES_VERIFIED')
stopifnot(fromJSON(file.path(maps,'status.json'))$status=='MAPS_RENDERED_VISUAL_QA_PENDING',fromJSON(file.path(figs,'status.json'))$status=='SUMMARY_FIGURES_RENDERED_VISUAL_QA_PENDING',fromJSON(file.path(clim,'status.json'))$status=='CLIMATE_FIGURE_RENDERED_VISUAL_QA_PENDING')
s<-read.csv(file.path(root,'paired/descriptive_summary.csv'));m<-read.csv(file.path(maps,'map_percentile_audit.csv'));stopifnot(nrow(s)==18,nrow(m)==3,all(m$native_cells==1943));field<-s[s$DHP=='Field',];eq(m$mean_delta,field$paired_difference[match(m$year,field$year)])
fits<-read.csv(file.path(root,'associations/soil_yield_R2.csv'));stopifnot(nrow(fits)==60,setequal(unique(fits$property),c('OC','pH','sand','silt','clay')),setequal(unique(fits$interval),c('0-30 cm','30-100 cm')),all(fits$n[fits$source=='DSM']==2030),all(fits$n[fits$source=='SSURGO']==6),all(fits$R2>=0&fits$R2<=1))
ranges<-read.csv(file.path(root,'variograms/variogram_parameters.csv'));stopifnot(nrow(ranges)==9,all(ranges$range_identified),all(is.finite(ranges$effective_range_m)))
slabs<-read.csv(file.path(figs,'depth_slabs.csv'));stopifnot(all(c('DSM','SSURGO')%in%unique(slabs$source)),all(c(0,200)%in%slabs$bottom),!anyNA(slabs$mean))
dir.create(out,recursive=TRUE);sources<-c(file.path(root,'results/status.json'),file.path(root,'independent_verification/status.json'),file.path(root,'paired/status.json'),file.path(root,'associations/status.json'),file.path(root,'variograms/status.json'),file.path(maps,'status.json'),file.path(figs,'status.json'),file.path(clim,'status.json'),file.path(review,'status.json'))
writej(list(status='PASS_SCIENTIFIC_ANALYSIS_FOR_AUTHOR_REVIEW',profiles=2036,DSM=2030,SSURGO=6,paired_cells=1943,years=c(2017,2019,2021),native_map_means_match=TRUE,regressions='Only raw OC, pH, sand, silt, clay; separate0-30 and30-100cm',field_results=field,source_statuses=data.frame(path=sources,md5=unname(tools::md5sum(sources))),recovery='First map attempt stopped at free-RAM guard before rendering; original failed status/logs retained. New map output folder passed. No simulation or statistic was overwritten.',visual_QA='Separate native Word and rendered-page review required for document release.'),file.path(out,'QA.json'))
capture.output(sessionInfo(),file=file.path(out,'sessionInfo.txt'))
